-- Pack fr — what has to be done, in France, for a roof photovoltaic project
-- and for an energy community: the templates `tasks.plan()` instantiates
-- when the `tasks` module is installed. Each names the text it answers.
set search_path = nexgen, public, extensions;

do $$
begin
  if to_regclass('tasks.templates') is null then
    raise notice 'pack fr: the tasks module is not installed, its templates are skipped';
    return;
  end if;

  insert into tasks.templates (code, published_by, country, project_kind, phase, role, name, description, legal_source_code, legal_reference, documents, applies_when, depends_on_code, position) values
    -- A photovoltaic installation on an existing roof.
    ('pv_roof_feasibility',       'pack:fr', 'FR', 'pv_roof', 'study',           'owner',         'Feasibility study: yield, self-consumption share, budget',                  'The roof, its orientation and shading, the site''s consumption curve, the expected yield and the share self-consumed, the budget and the return.', null, null, '{"Feasibility report"}', null, null, 10),
    ('pv_roof_structure',         'pack:fr', 'FR', 'pv_roof', 'design',          'installer',     'Structural check of the roof and electrical design',                        'The roof carries the arrays; the electrical design (strings, inverter, protections) follows NF C 15-100 and the UTE C 15-712-1 guide.', null, 'NF C 15-100; UTE C 15-712-1', '{"Structural note", "Single-line diagram"}', null, 'pv_roof_feasibility', 20),
    ('pv_roof_prior_declaration', 'pack:fr', 'FR', 'pv_roof', 'permitting',      'owner',         'Prior declaration of works filed with the municipality',                   'Panels on an existing building change its external aspect: a prior declaration (Cerfa 13703) with the municipality, which has one month to answer, two in a protected perimeter where the architect of the Bâtiments de France gives an opinion.', 'fr_code_urbanisme', 'R. 421-17', '{"Cerfa 13703", "Non-opposition decision"}', null, 'pv_roof_structure', 30),
    ('pv_roof_connection_request','pack:fr', 'FR', 'pv_roof', 'grid_connection', 'installer',     'Connection request filed with the distribution operator',                  'The request for injection (surplus or whole production) with the distribution operator of the municipality; the operator answers with a connection proposal and its cost.', 'fr_code_energie', 'L. 342-1 et suivants', '{"Connection proposal"}', null, 'pv_roof_prior_declaration', 40),
    ('pv_roof_purchase_contract', 'pack:fr', 'FR', 'pv_roof', 'financing',       'owner',         'Purchase-obligation contract requested for the surplus',                   'For an installation of 100 kWc or less, the request for a twenty-year purchase contract under the S21 order, at the tariff of the quarter of the complete connection request; the self-consumption premium comes with it.', 'fr_arrete_2021_10_06_s21', 'Article 1', '{"Purchase contract request"}', '{"property": "installed_power", "op": "<=", "value": 100}', 'pv_roof_connection_request', 45),
    ('pv_roof_tender',            'pack:fr', 'FR', 'pv_roof', 'financing',       'owner',         'Bid in the simplified call for tenders',                                    'For an installation above 100 kWc and up to 500 kWc on a building, the surplus or the production is sold through the simplified call for tenders of the regulator.', 'fr_arrete_2021_10_06_s21', 'Article 1, as amended on 26 March 2025', '{"Tender bid"}', '{"property": "installed_power", "op": ">", "value": 100}', 'pv_roof_connection_request', 46),
    ('pv_roof_procurement',       'pack:fr', 'FR', 'pv_roof', 'procurement',     'installer',     'Modules, inverter and mounting system ordered and delivered',               null, null, null, '{"Order", "Delivery note", "Datasheets"}', null, 'pv_roof_prior_declaration', 50),
    ('pv_roof_installation',      'pack:fr', 'FR', 'pv_roof', 'installation',    'installer',     'Arrays mounted and wired',                                                  null, null, null, '{"Photos of the installation"}', null, 'pv_roof_procurement', 60),
    ('pv_roof_consuel',           'pack:fr', 'FR', 'pv_roof', 'commissioning',   'installer',     'Attestation of conformity stamped by Consuel',                              'The installer files the attestation of conformity of the installation with Consuel, which stamps it, with or without a site visit; the operator energises nothing without it.', 'fr_code_energie', 'D. 342-16 à D. 342-21', '{"Attestation de conformité visée"}', null, 'pv_roof_installation', 70),
    ('pv_roof_energised',         'pack:fr', 'FR', 'pv_roof', 'grid_connection', 'grid_operator', 'Connection energised and meter set for injection',                          'The distribution operator connects the installation and programs the meter for injection; the purchase contract starts from this date.', 'fr_code_energie', 'L. 342-1 et suivants', '{"Commissioning report of the operator"}', null, 'pv_roof_consuel', 80),
    ('pv_roof_handover',          'pack:fr', 'FR', 'pv_roof', 'handover',        'installer',     'Installation handed over with its file',                                    'Diagrams, datasheets, warranties, the attestation of conformity, the monitoring access, handed to the owner.', null, null, '{"Handover file"}', null, 'pv_roof_energised', 90),
    -- An energy community: a collective self-consumption operation.
    ('acc_perimeter_check',       'pack:fr', 'FR', 'energy_community', 'study',           'community_manager', 'Perimeter and power checked against the order',                 'The two furthest connection points within 2 km (10 km or 20 km in rural areas with the minister''s derogation), the cumulative production below 5 MW; the list of candidate participants and their PRMs.', 'fr_arrete_2019_11_21_acc', 'Article 1', '{"Map of the perimeter", "List of participants"}', null, null, 10),
    ('acc_power_over_cap',        'pack:fr', 'FR', 'energy_community', 'study',           'community_manager', 'Production above 5 MW: split the operation or claim the public-entity perimeter', 'The cumulative production exceeds the 5 MW ceiling of an extended operation: either several operations, or the perimeter of an inter-municipal body when every participant carries a public service mission.', 'fr_arrete_2019_11_21_acc', 'Article 1 and article 1 bis', '{}', '{"property": "installed_power", "op": ">=", "value": 5000}', 'acc_perimeter_check', 15),
    ('acc_organising_entity',     'pack:fr', 'FR', 'energy_community', 'design',          'community_manager', 'Organising entity constituted, statutes signed',                 'The legal entity that organises the operation: an association, a cooperative, a mixed-economy company, a local authority, a landlord or a co-ownership; its statutes name the operation.', 'fr_code_energie', 'L. 315-2', '{"Statutes", "Registration"}', null, 'acc_perimeter_check', 20),
    ('acc_allocation_key',        'pack:fr', 'FR', 'energy_community', 'design',          'community_manager', 'Allocation key chosen and written in the participants'' agreement', 'Static, dynamic by default or dynamic custom, by time band if wanted, on the 30-minute step; the internal price of the shared energy and the rules of entry and exit.', 'fr_enedis_noi_cf_110e', null, '{"Participants'' agreement"}', null, 'acc_organising_entity', 30),
    ('acc_convention',            'pack:fr', 'FR', 'energy_community', 'permitting',      'community_manager', 'Collective self-consumption convention signed with the distribution operator', 'The operator''s convention: perimeter, connection points, key, data returned, declaration of changes.', 'fr_enedis_convention_acc', null, '{"Signed convention"}', null, 'acc_allocation_key', 40),
    ('acc_participant_consents',  'pack:fr', 'FR', 'energy_community', 'permitting',      'community_manager', 'Participants'' adhesions and consents to the use of their meter data collected', 'Each participant adheres to the operation and consents to the operator sharing its 30-minute data with the organising entity.', 'fr_enedis_data_connect_terms', null, '{"Adhesion forms", "Consents"}', null, 'acc_organising_entity', 50),
    ('acc_points_declared',       'pack:fr', 'FR', 'energy_community', 'grid_connection', 'grid_operator',     'Connection points declared and activated by the operator',       'The operator checks each PRM, activates the operation and starts allocating on the first day of a month.', 'fr_enedis_convention_acc', null, '{"Activation notice"}', null, 'acc_convention', 60),
    ('acc_first_allocation',      'pack:fr', 'FR', 'energy_community', 'commissioning',   'community_manager', 'First month of allocated curves received and checked',           'The allocated self-consumed and surplus curves of the first month, at the 30-minute step, against the key.', 'fr_enedis_convention_acc', null, '{"Allocated curves"}', null, 'acc_points_declared', 70),
    ('acc_monthly_settlement',    'pack:fr', 'FR', 'energy_community', 'operation',       'community_manager', 'Monthly settlement and invoicing of the shared energy',          'Each month, from the operator''s curves: the shared energy of each consumer at the internal price, the producers'' share, the surplus sold.', 'fr_enedis_convention_acc', null, '{"Settlement statement", "Invoices"}', null, 'acc_first_allocation', 80),
    ('acc_changes_declared',      'pack:fr', 'FR', 'energy_community', 'operation',       'community_manager', 'Entries, exits and key changes declared to the operator',         null, 'fr_enedis_convention_acc', null, '{}', null, 'acc_points_declared', 90);
